<flux:modal name="receipt-lookup" data-theme="light" class="sale-dialog sale-tuition-dialog">
    <div class="space-y-5">
        <div class="sale-modal-heading"><p class="sale-label">Seleccionar</p><h2 class="mt-1 text-xl font-semibold" x-text="{ clients: 'Cliente del catálogo actual', students: 'Alumno', client_cxc: 'CXC de cliente', academic_cxc: 'CXC de alumno' }[lookupKind]"></h2><p class="mt-1 text-xs" x-show="lookupKind.includes('cxc')">Selecciona una factura pendiente para completar el formulario.</p></div>
        <div class="grid items-end gap-3" :class="lookupKind === 'academic_cxc' ? 'sm:grid-cols-[minmax(0,1fr)_6rem_10rem_auto]' : 'sm:grid-cols-[minmax(0,1fr)_auto]'">
            <flux:input label="Buscar" size="sm" icon="magnifying-glass" x-model="lookupQuery" x-on:input.debounce.350ms="loadLookup()" maxlength="100" placeholder="Nombre, documento, carnet o factura" />
            <flux:input x-show="lookupKind === 'academic_cxc'" label="Año" size="sm" type="number" min="2000" max="2100" x-model="lookupYear" placeholder="Todos" />
            <x-catalog-select name="receipt-lookup-funding" label="Responsable" size="sm" :options="$receiptFundingChoices" :required="true" value="normal" x-show="lookupKind === 'academic_cxc'" x-model="lookupFunding" x-on:change="loadLookup()" x-effect="disabled = locked || selecting" />
            <flux:button size="sm" x-on:click="loadLookup()" x-bind:disabled="lookupLoading || selecting">Consultar</flux:button>
        </div>
        <p x-show="notice" class="text-xs text-amber-700" role="status" x-text="notice"></p><p x-show="lookupLoading || selecting" class="text-xs text-zinc-500" role="status">Consultando…</p>
        <div class="max-h-[55dvh] overflow-auto rounded-xl border border-zinc-200"><table class="sale-workspace-table w-full text-left text-xs"><thead class="sticky top-0 bg-zinc-100 text-zinc-500"><tr><th>Nombre / Alumno</th><th x-show="lookupKind.includes('cxc')">Concepto / Factura</th><th x-show="lookupKind.includes('cxc')" class="text-right!">Facturado</th><th x-show="lookupKind.includes('cxc')" class="text-right!">Pendiente</th><th></th></tr></thead><tbody class="divide-y divide-zinc-200"><template x-for="row in lookupRows" :key="row.key || row.id"><tr><td><p class="text-sm font-medium" x-text="row.studentName || row.name"></p><p class="mt-1 font-mono text-[11px] text-zinc-500" x-text="row.studentId || row.document || ''"></p><p class="mt-1 text-[11px] text-zinc-500" x-show="row.payerName" x-text="row.payerName"></p></td><td x-show="lookupKind.includes('cxc')"><p class="break-all" x-text="row.invoice || row.name"></p><p class="mt-1 text-zinc-500" x-text="row.year || ''"></p></td><td x-show="lookupKind.includes('cxc')" class="text-right tabular-nums" x-text="money(cents(row.amount))"></td><td x-show="lookupKind.includes('cxc')" class="text-right font-semibold tabular-nums" x-text="money(cents(row.remaining))"></td><td><flux:button size="xs" x-on:click="choose(row)" x-bind:disabled="locked || selecting">Seleccionar</flux:button></td></tr></template></tbody></table><p x-show="!lookupLoading && !lookupRows.length" class="p-8 text-center text-xs text-zinc-500">No hay resultados disponibles.</p></div>
        <div class="flex items-center justify-end gap-3"><flux:button size="xs" x-on:click="loadLookup(lookupPage - 1)" x-bind:disabled="lookupLoading || lookupPage <= 1">Anterior</flux:button><span class="text-xs text-zinc-500" x-text="`${lookupPage} / ${lookupPages}`"></span><flux:button size="xs" x-on:click="loadLookup(lookupPage + 1)" x-bind:disabled="lookupLoading || lookupPage >= lookupPages">Siguiente</flux:button></div>
    </div>
</flux:modal>
<flux:modal name="receipt-copy" data-theme="light" class="w-full max-w-lg"><div class="space-y-4"><flux:heading size="lg">Recibo registrado</flux:heading><p class="font-mono text-sm font-semibold" x-text="completed?.number"></p><p class="text-sm" x-text="completed?.recipient"></p><p class="text-xs text-zinc-500" x-text="statusLabel(completed?.status)"></p><template x-for="error in completed?.errors || []" :key="error"><p class="text-xs text-amber-700" x-text="error"></p></template><p x-show="notice" class="text-xs text-amber-700" x-text="notice"></p><p class="text-sm">¿Deseas una copia del comprobante?</p><div class="flex justify-end gap-3"><flux:button x-on:click="finish()">No, continuar</flux:button><flux:button variant="primary" x-show="options.canPrint" x-on:click="finish(true)">Sí, abrir copia</flux:button></div></div></flux:modal>
<flux:modal name="receipt-reset" data-theme="light" class="w-full max-w-md"><div class="space-y-4"><flux:heading size="lg">Nuevo recibo</flux:heading><p class="text-sm">Se limpiarán los datos de la operación que estás preparando.</p><div class="flex justify-end gap-3"><flux:modal.close><flux:button>Volver</flux:button></flux:modal.close><flux:button variant="primary" x-on:click="reset()" x-bind:disabled="locked">Limpiar formulario</flux:button></div></div></flux:modal>
<flux:modal name="receipt-history" data-theme="light" variant="flyout" class="w-full md:w-[52rem]">
    <div class="space-y-5">
        <div class="sale-modal-heading"><p class="sale-label">Librería</p><h2 class="mt-1 text-xl font-semibold">Historial de recibos</h2><p class="mt-1 text-xs">Consulta comprobantes, copias y aplicaciones pendientes.</p></div>
        <div class="grid items-end gap-3 sm:grid-cols-[minmax(0,1fr)_12rem_auto]"><flux:input label="Buscar en historial" size="sm" icon="magnifying-glass" x-model="historyQuery" x-bind:placeholder="historyLegacy ? 'Nombre de la persona' : 'Persona, alumno o carnet'" x-on:input.debounce.350ms="loadHistory()" /><x-catalog-select name="receipt-history-origin" label="Origen" size="sm" :options="$receiptHistoryChoices" :required="true" value="current" x-model="historyOrigin" x-on:change="loadHistory()" x-effect="disabled = historyLoading" /><flux:button size="sm" x-on:click="loadHistory()" x-bind:disabled="historyLoading">Actualizar</flux:button></div>
        <p x-show="historyLoading" class="text-xs text-zinc-500">Cargando historial…</p>
        <p x-show="notice" class="text-xs text-amber-700" role="status" x-text="notice"></p>
        <div class="overflow-x-auto rounded-xl border border-zinc-200">
            <table class="sale-workspace-table w-full text-left text-xs">
                <thead class="bg-zinc-100 text-zinc-500"><tr><th>Recibo</th><th>Destinatario / alumno</th><th>Estado</th><th class="text-right!">Total</th><th></th></tr></thead>
                <tbody class="divide-y divide-zinc-200">
                    <template x-for="row in history" :key="(row.legacy ? 'old' : 'new') + row.id">
                        <tr>
                            <td><p class="font-mono text-[11px]" x-text="row.number"></p><p class="mt-1 text-[10px] text-zinc-500" x-text="row.date"></p></td>
                            <td>
                                <p class="font-medium" x-text="row.recipient"></p>
                                <div x-show="row.student" class="mt-2 rounded-lg bg-zinc-100 px-2.5 py-2"><p class="sale-label">Alumno</p><p class="mt-1 text-[11px]" x-text="row.student?.name || ''"></p><p class="mt-1 font-mono text-[10px] text-zinc-500" x-text="row.student?.id || ''"></p></div>
                                <p class="mt-2 text-[10px] text-zinc-500" x-text="`${row.operator} · ${row.register}`"></p>
                            </td>
                            <td><span class="rounded-md bg-brand-yellow/10 px-2 py-1 text-[10px] font-medium" x-text="statusLabel(row.status)"></span><template x-for="error in row.errors" :key="error"><p class="mt-2 max-w-48 text-[11px] text-amber-700" x-text="error"></p></template></td>
                            <td class="text-right font-medium tabular-nums" x-text="money(cents(row.total))"></td>
                            <td><div class="flex flex-wrap justify-end gap-2"><a x-show="options.canPrint" :href="row.ticketUrl" target="_blank" rel="noopener" class="rounded-lg border border-zinc-200 px-2 py-1.5 text-[11px]">Copia</a><flux:button size="xs" x-show="!row.legacy && options.canRetry && ['PENDIENTE_APLICACION','REVISION','ANULACION_PENDIENTE'].includes(row.status)" x-on:click="retry(row)" x-bind:disabled="busy">Reintentar</flux:button><flux:button size="xs" variant="ghost" x-show="!row.legacy && options.canAnnul && !['ANULADO','ANULACION_PENDIENTE'].includes(row.status)" x-on:click="annulment = { row, reason: '' }; $flux.modal('receipt-annul').show()" x-bind:disabled="busy">Anular</flux:button></div></td>
                        </tr>
                    </template>
                </tbody>
            </table>
            <p x-show="!historyLoading && !history.length" class="p-8 text-center text-xs text-zinc-500">No hay recibos que coincidan con tu búsqueda.</p>
        </div>
        <div class="flex items-center justify-end gap-3"><flux:button size="xs" x-on:click="loadHistory(historyPage - 1)" x-bind:disabled="historyLoading || historyPage <= 1">Anterior</flux:button><span class="text-xs text-zinc-500" x-text="`${historyPage} / ${historyPages}`"></span><flux:button size="xs" x-on:click="loadHistory(historyPage + 1)" x-bind:disabled="historyLoading || historyPage >= historyPages">Siguiente</flux:button></div>
    </div>
</flux:modal>
<flux:modal data-theme="light" name="receipt-annul" class="w-full max-w-lg"><form x-on:submit.prevent="annul()" class="space-y-4"><flux:heading size="lg">Anular recibo completo</flux:heading><p class="text-sm" x-text="annulment.row?.number"></p><p class="text-zinc-500 text-sm">Se revertirán sus aplicaciones confirmadas. No se registra una devolución automática de dinero.</p><flux:textarea label="Motivo" x-model="annulment.reason" required minlength="5" maxlength="500" /><div class="flex justify-end gap-3"><flux:modal.close><flux:button>Cancelar</flux:button></flux:modal.close><flux:button type="submit" variant="primary" x-bind:disabled="busy">Confirmar anulación</flux:button></div></form></flux:modal>
<flux:modal name="receipt-academic-detail" data-theme="light" class="sale-dialog w-full max-w-xl" x-on:close="cancelAcademic()">
    <form x-on:submit.prevent="addAcademic()" class="space-y-5">
        <div class="pr-8"><p class="sale-label">Agregar al recibo</p><h2 class="mt-2 text-xl font-semibold" x-text="selection?.name || 'Cuota del alumno'"></h2><p class="mt-1 text-xs text-zinc-500" x-text="form.studentName + ' · ' + fundingLabel(form.funding)"></p></div>
        <p x-show="notice" class="rounded-lg border border-amber-400/30 bg-amber-400/10 px-3 py-2 text-xs text-amber-800" role="status" x-text="notice"></p>
        <fieldset x-bind:disabled="locked || selecting" class="min-w-0 space-y-5">
            <div class="grid grid-cols-2 items-center gap-4 rounded-xl bg-zinc-100 p-4"><div><p class="sale-label">Saldo pendiente</p><p class="mt-2 text-xl font-semibold tabular-nums" x-text="money(cents(selection?.remaining))"></p></div><div><flux:input label="Abono a esta cuota" size="sm" type="number" required min="0.01" step="0.01" x-bind:max="selection?.remaining" x-model="form.amount" /><p class="mt-1.5 text-[11px] text-zinc-500">Puedes pagar una parte o el total.</p></div></div>
            <div x-show="form.invoiceAutomatic" class="rounded-xl border border-emerald-600/15 bg-emerald-600/5 p-3"><p class="text-xs font-semibold text-emerald-800">Factura identificada</p><p class="mt-1 break-all font-mono text-[11px] text-zinc-500" x-text="form.invoice?.number"></p></div>
            <details x-bind:open="!form.invoiceAutomatic || !selection?.account" class="rounded-xl border border-zinc-200 p-4">
                <summary class="cursor-pointer text-xs font-medium">Factura de origen y cuenta contable</summary>
                <div class="mt-4 space-y-4">
                    <x-catalog-select name="receipt-academic-invoice" label="Factura de origen" size="sm" :required="true" :dynamic-options="true" placeholder="Busca la factura correspondiente…" x-model="invoiceChoice" x-on:change="chooseInvoice()" x-effect="setOptions(invoices.map(row => ({ value: row.origin + '|' + row.uuid, label: row.number + ' · ' + money(cents(row.amount)) })), locked || selecting)" />
                    <flux:checkbox x-show="form.invoice && !form.invoiceAutomatic" x-model="form.invoiceConfirmed" label="Confirmo que corresponde al alumno, concepto y año seleccionados" />
                    <x-catalog-select name="receipt-academic-account" label="Cuenta por cobrar" size="sm" :options="$receiptAccountChoices" :show-code="true" :required="true" placeholder="Busca por código o nombre…" x-model="form.account" x-effect="disabled = locked || selecting" />
                    <div class="flex items-end gap-2"><flux:input label="Buscar otra factura" size="sm" x-model="invoiceQuery" maxlength="100" placeholder="Número de control o código de generación" class="min-w-0 flex-1" /><flux:button size="sm" x-on:click="prepare(invoiceQuery)">Buscar</flux:button></div>
                </div>
            </details>
        </fieldset>
        <div class="flex items-center justify-end gap-3 border-t border-zinc-200 pt-4"><flux:modal.close><flux:button size="sm">Cancelar</flux:button></flux:modal.close><flux:button type="submit" variant="primary" size="sm" icon="plus" x-bind:disabled="locked || selecting"><span x-text="selecting ? 'Consultando…' : 'Agregar cuota'"></span></flux:button></div>
    </form>
</flux:modal>
